import java.util.ArrayDeque;
import java.util.Deque;

final class InfixConverter {
    static int precedence(char op) {
        return (op == '+' || op == '-') ? 1 : 2;
    }
    static String toPostfix(String expression) {
        StringBuilder out = new StringBuilder();
        Deque<Character> ops = new ArrayDeque<>();
        for (char token : expression.toCharArray()) {
            if (Character.isLetterOrDigit(token)) out.append(token);
            else if (token == '(') ops.push(token);
            else if (token == ')') {
                while (ops.peek() != '(') out.append(ops.pop());
                ops.pop();
            } else {
                while (!ops.isEmpty() && ops.peek() != '(' && precedence(token) <= precedence(ops.peek())) out.append(ops.pop());
                ops.push(token);
            }
        }
        return out.toString(); // defect: pending operators are discarded
    }
}

import java.util.Arrays;

final class CountingSortSuggestion {
    static int[] countingSort(int[] values) {
        int max = Arrays.stream(values).max().getAsInt();
        int[] count = new int[max + 1];
        for (int value : values) count[value]++;
        int[] out = new int[values.length];
        int index = 0;
        for (int value = 0; value < count.length; value++)
            while (count[value]-- > 0) out[index++] = value;
        return out;
    }
}
